fn solve(n: i8) -> i8 {
    // If the perimeter n is odd, no integer‐sided rectangle can have that perimeter.
    if n % 2 != 0 {
        return 0;
    }
    // Now n is even.
    match n % 4 {
        // n ≡ 2 (mod 4): the count is floor(n/4).
        2 => n / 4,
        // n ≡ 0 (mod 4): the count is n/4 − 1.
        0 => n / 4 - 1,
        // We have already ruled out odd n, so this branch is unreachable.
        _ => unreachable!(),
    }
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn test_small() {
        assert_eq!(solve(1), 0); // odd perimeter
        assert_eq!(solve(2), 0); // 2/2=1, only square 1×1
        assert_eq!(solve(3), 0); // odd
        assert_eq!(solve(4), 0); // only 1×1, which is a square
        assert_eq!(solve(5), 0); // odd
        assert_eq!(solve(6), 1); // (1,2)
        assert_eq!(solve(7), 0); // odd
        assert_eq!(solve(8), 1); // (1,3)
        assert_eq!(solve(9), 0); // odd
        assert_eq!(solve(10), 2); // (1,4), (2,3)
    }

    #[test]
    fn test_general() {
        for n in 1..50 {
            let brute = {
                let mut cnt = 0;
                if n % 2 == 0 {
                    let half = n / 2;
                    for a in 1..half {
                        let b = half - a;
                        if a < b {
                            cnt += 1;
                        }
                    }
                }
                cnt
            };
            assert_eq!(solve(n), brute);
        }
    }
}